
create or replace function public._conv_link(_conv uuid) returns text language sql immutable set search_path=public as $$ select '/app/communication?c=' || _conv $$;
do $$ declare f text; begin
  foreach f in array array['conv_access_ok(uuid)','is_conv_member(uuid)','can_read_conv_at(uuid,timestamptz)','_eligible_staff(uuid,uuid,uuid)','_scope_manager(uuid,uuid)','_family_ok(uuid,uuid,uuid,text)','conv_send_block(uuid)','can_read_circular(uuid)','_file_policy(uuid)','create_message_file(uuid,text,text,bigint)','send_message(uuid,text,uuid,uuid,uuid[])','edit_message(uuid,text)','delete_message(uuid)','mark_conversation_read(uuid,bigint)','set_member_prefs(uuid,boolean,boolean)','my_conversations(uuid)','search_messages(text,uuid)','conversation_people(uuid)','teacher_students(uuid)','family_contacts(uuid)','guardian_contacts(uuid)','start_family_conversation(uuid,uuid,uuid)','staff_directory(uuid,uuid)','start_direct_conversation(uuid,uuid)','_group_admin(uuid)','create_group(uuid,uuid,text,text,text,text,uuid,text,boolean,text,date,uuid,uuid[],uuid[],uuid,text)','add_group_members(uuid,uuid[])','remove_group_member(uuid,uuid)','set_group_role(uuid,uuid,text)','transfer_group_owner(uuid,uuid)','leave_group(uuid)','set_group_status(uuid,text)','update_group_settings(uuid,timestamptz,text,text,text,boolean,text,date)','report_message(uuid,text,uuid)','report_detail(uuid)','decide_report(uuid,text,text,boolean)','preview_circular_audience(uuid,jsonb)','save_circular(uuid,uuid,text,text,text,text,boolean,date,jsonb)','publish_circular(uuid)','revise_circular(uuid,text,text,boolean)','archive_circular(uuid)','open_circular(uuid)','ack_circular(uuid)','circular_stats(uuid)','remind_circular_ack(uuid)','create_circular_file(uuid,text,text,bigint)','can_read_file(uuid)'] loop
    execute format('revoke execute on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
